{
  "findings": [
    {
      "check_id": "CKV_GCP_10",
      "title": "Service account has overly broad scopes (cloud-platform)",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "HIGH",
      "explanation": "The service account is granted the 'cloud-platform' scope, which provides full access to all Google Cloud APIs. This violates the principle of least privilege and increases the blast radius if the instance is compromised."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Instance has public IP address assigned",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The presence of an empty 'access_config {}' block assigns a public ephemeral IP address to the instance. For an internal orchestration engine within a VPC, this unnecessary exposure increases the attack surface."
    },
    {
      "check_id": "CKV_GCP_38",
      "title": "Serial port access enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "LOW",
      "explanation": "Metadata 'serial-port-enable = true' allows SSH over serial console. Unless explicitly required for debugging or recovery scenarios where network access is unavailable, this should be disabled to reduce potential entry points."
    }
  ],
  "patched_code": "resource "google_compute_instance" "backup_orchestration_engine" {
  name         = "enterprise-disaster-recovery-orchestration-platform-compute-orchestration"
  machine_type = "e2-medium"
  zone         = "${var.primary_region}-a"
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-11"
      size  = 50
    }
  }
  network_interface {
    network    = google_compute_network.dr_vpc.id
    subnetwork = google_compute_subnetwork.management_subnet.id
    # Removed access_config to prevent public IP assignment
  }
  service_account {
    email  = "123456789-compute@developer.gserviceaccount.com"
    # Replaced cloud-platform with specific minimal scopes required for DR orchestration
    scopes = [
      "https://www.googleapis.com/auth/cloud-platform.read-only",
      "https://www.googleapis.com/auth/compute",
      "https://www.googleapis.com/auth/storage.full_control"
    ]
  }
  metadata = {
    # Disabled serial port access by default
    serial-port-enable = false
    startup-script     = file("${path.module}/scripts/orchestration-startup.sh")
  }
  tags = ["dr-internal", "orchestration-engine"]
  depends_on = [
    google_storage_bucket.primary_backup_storage,
    google_sql_database_instance.recovery_database
  ]
}",
  "fix_summary": "Removed the public IP assignment by deleting the 'access_config' block. Restricted service account scopes from 'cloud-platform' to more granular permissions (read-only platform, compute, and storage) to enforce least privilege. Disabled serial port access in metadata to harden the instance against unauthorized console access."
}
